pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // Ensure the inputs have the same length
    assert_eq!(
        condition.len(),
        arr.len(),
        "The boolean mask and the array must have the same length"
    );

    // Pre-allocate enough space to hold all true-selected elements
    let true_count = condition.iter().filter(|&&b| b).count();
    let mut result = Vec::with_capacity(true_count);

    // Zip together the mask and values, push the value if the mask is true
    for (keep, value) in condition.into_iter().zip(arr.into_iter()) {
        if keep {
            result.push(value);
        }
    }

    result
}